const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'TIOBE Index March 2026'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Decorative geometric shapes on right side
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.5, y: -0.5, w: 4.5, h: 3.5,
    fill: { color: theme.secondary, transparency: 70 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.2, y: 2.0, w: 3.8, h: 4.0,
    fill: { color: theme.accent, transparency: 75 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 8.0, y: 0.5, w: 2.5, h: 2.5,
    fill: { color: theme.light, transparency: 80 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 4.0, w: 2.0, h: 2.0,
    fill: { color: theme.bg, transparency: 78 }
  });

  // Left accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.2, w: 0.08, h: 1.8,
    fill: { color: theme.accent }
  });

  // Main title
  slide.addText("TIOBE Index March 2026:", {
    x: 0.8, y: 1.2, w: 5.8, h: 0.7,
    fontSize: 32, fontFace: "Georgia",
    color: theme.accent, bold: true,
    align: "left", valign: "middle", margin: 0
  });
  slide.addText("How 20+ Search Engines Rank the World's Programming Languages", {
    x: 0.8, y: 1.85, w: 5.8, h: 1.2,
    fontSize: 28, fontFace: "Georgia",
    color: "FFFFFF", bold: true,
    align: "left", valign: "top", margin: 0
  });

  // Subtitle
  slide.addText("Python leads at 21.25% but posts the largest year-over-year decline among the top 5, while C surges to second and Go drops from 7th to 16th.", {
    x: 0.8, y: 3.3, w: 5.5, h: 1.0,
    fontSize: 13, fontFace: "Calibri",
    color: "FFFFFF", bold: false,
    align: "left", valign: "top", margin: 0,
    transparency: 15
  });

  // Separator line
  slide.addShape(pres.shapes.LINE, {
    x: 0.8, y: 4.5, w: 3.0, h: 0,
    line: { color: theme.accent, width: 1.5 }
  });

  // Meta info
  slide.addText("March 2026  |  Data Analysis Report  |  Source: tiobe.com/tiobe-index", {
    x: 0.8, y: 4.7, w: 5.5, h: 0.4,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", bold: false,
    align: "left", valign: "middle", margin: 0,
    transparency: 30
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "e76f51"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

