  });

  // Gainers data
  var gainers = [
    { name: "Perl", from: "24th", to: "11th", spots: "+13", pp: "+1.05 pp" },
    { name: "R", from: "16th", to: "9th", spots: "+7", pp: "+0.94 pp" },
