    { name: "Python", from: "1st", to: "1st", spots: "0", pp: "-2.59 pp" }
  ];

  var rowStartY = 1.55;
  var rowH = 0.72;

  gainers.forEach(function(item, i) {
    var y = rowStartY + i * rowH;
    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: colLeftX, y: y, w: colW, h: rowH - 0.08,
