      fontSize: 11, fontFace: "Calibri",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle", margin: 0
    });
    // PP change
    slide.addText(item.pp, {
      x: colRightX + 3.7, y: y, w: 0.7, h: rowH - 0.08,
      fontSize: 10, fontFace: "Calibri",
      color: theme.bg, bold: false,
      align: "right", valign: "middle", margin: 0
    });
  });

  // Insight callout at bottom
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 4.55, w: 9.2, h: 0.5,
    fill: { color: theme.primary, transparency: 92 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 4.55, w: 0.06, h: 0.5,
    fill: { color: theme.accent }
  });
  slide.addText("Go\u2019s drop from 7th to 16th (\u22121.49 pp) is the sharpest fall \u2014 contrasting with its 2016 Language of the Year win", {
    x: 0.6, y: 4.55, w: 8.8, h: 0.5,
