const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 4,
  title: 'Historical Trends'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText("From Lisp at #2 in 1986 to Python at #1 in 2026: How Language Rankings Shifted Over Time", {
    x: 0.4, y: 0.2, w: 9.2, h: 0.55,
    fontSize: 18, fontFace: "Georgia",
    color: theme.primary, bold: true,
    align: "left", valign: "middle", margin: 0,
    fit: "shrink"
  });

  // Table header and data
  var years = ["2026", "2021", "2016", "2011", "2006", "2001", "1996", "1991", "1986"];
  var langData = [
    { name: "Python",     ranks: ["1","3","5","7","8","26","17","\u2014","\u2014"] },
    { name: "C",          ranks: ["2","1","2","2","2","1","1","1","1"] },
    { name: "C++",        ranks: ["3","4","3","3","3","2","2","2","9"] },
    { name: "Java",       ranks: ["4","2","1","1","1","3","31","\u2014","\u2014"] },
    { name: "C#",         ranks: ["5","5","4","5","7","11","\u2014","\u2014","\u2014"] },
    { name: "JavaScript", ranks: ["6","7","8","10","10","8","33","\u2014","\u2014"] },
    { name: "Go",         ranks: ["10","11","60","16","\u2014","\u2014","\u2014","\u2014","\u2014"] },
    { name: "Ada",        ranks: ["14","36","25","22","16","18","6","10","3"] },
    { name: "Lisp",       ranks: ["26","34","26","13","14","19","8","4","2"] }
  ];

  // Build table rows
  var headerRow = [
    { text: "Language", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 9, fontFace: "Georgia", align: "left", valign: "middle" } }
  ];
  years.forEach(function(yr) {
    headerRow.push({
      text: yr,
      options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 9, fontFace: "Calibri", align: "center", valign: "middle" }
    });
  });

  var tableRows = [headerRow];

  langData.forEach(function(lang, rowIdx) {
    var rowBg = rowIdx % 2 === 0 ? "F7F9FA" : "FFFFFF";
    var row = [
      { text: lang.name, options: { fill: { color: rowBg }, color: theme.primary, bold: true, fontSize: 9, fontFace: "Georgia", align: "left", valign: "middle" } }
    ];
    lang.ranks.forEach(function(rank, colIdx) {
      var cellBg = rowBg;
      var cellColor = theme.primary;
      var cellBold = false;

      // Highlight Python #1 in 2026
      if (lang.name === "Python" && colIdx === 0) {
        cellBg = theme.accent;
        cellColor = theme.primary;
        cellBold = true;
      }
      // Highlight C's top-2 consistency
      if (lang.name === "C" && rank !== "\u2014" && parseInt(rank) <= 2) {
        cellBg = theme.secondary;
        cellColor = "FFFFFF";
        cellBold = true;
      }
      // Highlight Lisp's 1986 rank
      if (lang.name === "Lisp" && colIdx === 8) {
        cellBg = theme.light;
        cellColor = "FFFFFF";
        cellBold = true;
      }
      // Dim dashes
      if (rank === "\u2014") {
        cellColor = "BBBBBB";
      }

      row.push({
        text: rank,
        options: { fill: { color: cellBg }, color: cellColor, bold: cellBold, fontSize: 9, fontFace: "Calibri", align: "center", valign: "middle" }
      });
    });
    tableRows.push(row);
  });

  slide.addTable(tableRows, {
    x: 0.4, y: 0.85, w: 9.2,
    colW: [1.3, 0.88, 0.88, 0.88, 0.88, 0.88, 0.88, 0.88, 0.88, 0.88],
    rowH: [0.32, 0.32, 0.32, 0.32, 0.32, 0.32, 0.32, 0.32, 0.32, 0.32],
    border: { pt: 0.5, color: "DEE2E6" },
    margin: [2, 4, 2, 4]
  });

  // Key observations below table
  var obsY = 4.15;
  var obsData = [
    { num: "1", text: "C is the only language in the top 2 across all nine measurement points spanning four decades" },
    { num: "2", text: "Python rose from unranked (pre-1991) to #1 in approximately 25 years" },
    { num: "3", text: "Lisp fell from #2 in 1986 to #26 in 2026 \u2014 the most dramatic long-term decline" }
  ];

  obsData.forEach(function(obs, i) {
    var y = obsY + i * 0.33;
    // Number circle
    slide.addShape(pres.shapes.OVAL, {
      x: 0.5, y: y + 0.02, w: 0.25, h: 0.25,
      fill: { color: theme.secondary }
    });
    slide.addText(obs.num, {
      x: 0.5, y: y + 0.02, w: 0.25, h: 0.25,
      fontSize: 9, fontFace: "Calibri",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle", margin: 0
    });
    slide.addText(obs.text, {
      x: 0.85, y: y, w: 8.5, h: 0.3,
      fontSize: 10, fontFace: "Calibri",
      color: theme.primary, bold: false,
      align: "left", valign: "middle", margin: 0
    });
  });

  // Source
  slide.addText("Source: TIOBE Programming Community Index, March 2026", {
    x: 0.4, y: 5.25, w: 5, h: 0.3,
    fontSize: 8, fontFace: "Calibri",
    color: "999999", align: "left", valign: "middle", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "e76f51"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

