const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 5,
  title: 'Hall of Fame'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText("Python Wins Language of the Year 6 Times \u2014 More Than Any Other Language", {
    x: 0.4, y: 0.2, w: 9.2, h: 0.55,
    fontSize: 19, fontFace: "Georgia",
    color: theme.primary, bold: true,
    align: "left", valign: "middle", margin: 0,
    fit: "shrink"
  });

  // Left stat callout area
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 0.95, w: 2.6, h: 3.8,
    fill: { color: theme.primary }
  });
  slide.addText("6x", {
    x: 0.4, y: 1.1, w: 2.6, h: 1.0,
    fontSize: 60, fontFace: "Georgia",
    color: theme.accent, bold: true,
    align: "center", valign: "middle", margin: 0
  });
  slide.addText("Python", {
    x: 0.4, y: 2.0, w: 2.6, h: 0.4,
    fontSize: 18, fontFace: "Georgia",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle", margin: 0
  });
  slide.addText("Language of the Year", {
    x: 0.4, y: 2.35, w: 2.6, h: 0.35,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: false,
    align: "center", valign: "middle", margin: 0,
    transparency: 20
  });

  // Python winning years
  var pyYears = ["2007", "2010", "2018", "2020", "2021", "2024"];
  var pyStartY = 2.85;
  pyYears.forEach(function(yr, i) {
    var row = Math.floor(i / 3);
    var col = i % 3;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.55 + col * 0.78, y: pyStartY + row * 0.4, w: 0.7, h: 0.3,
      fill: { color: theme.secondary }
    });
    slide.addText(yr, {
      x: 0.55 + col * 0.78, y: pyStartY + row * 0.4, w: 0.7, h: 0.3,
      fontSize: 10, fontFace: "Calibri",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle", margin: 0
    });
  });

  // C# note
  slide.addText("C# won 2x (2023, 2025)", {
    x: 0.5, y: 3.85, w: 2.4, h: 0.3,
    fontSize: 9, fontFace: "Calibri",
    color: theme.accent, bold: false,
    align: "center", valign: "middle", margin: 0
  });
  slide.addText("driven by .NET ecosystem growth", {
    x: 0.5, y: 4.1, w: 2.4, h: 0.25,
    fontSize: 8, fontFace: "Calibri",
    color: "FFFFFF", bold: false,
    align: "center", valign: "middle", margin: 0,
    transparency: 30
  });

  // Right side: Timeline grid of winners 2016-2025
  var winners = [
    { year: "2025", lang: "C#", color: theme.accent },
    { year: "2024", lang: "Python", color: theme.secondary },
    { year: "2023", lang: "C#", color: theme.accent },
    { year: "2022", lang: "C++", color: theme.light },
    { year: "2021", lang: "Python", color: theme.secondary },
    { year: "2020", lang: "Python", color: theme.secondary },
    { year: "2019", lang: "C", color: theme.light },
    { year: "2018", lang: "Python", color: theme.secondary },
    { year: "2017", lang: "N/A", color: "BBBBBB" },
    { year: "2016", lang: "Go", color: theme.bg }
  ];

  var gridX = 3.4;
  var gridW = 6.0;
  var cardW = 2.8;
  var cardH = 0.6;
  var gapX = 0.3;
  var gapY = 0.12;
  var gridStartY = 0.95;

  winners.forEach(function(w, i) {
    var col = i % 2;
    var row = Math.floor(i / 2);
    var cx = gridX + col * (cardW + gapX);
    var cy = gridStartY + row * (cardH + gapY);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cy, w: cardW, h: cardH,
      fill: { color: w.color, transparency: 82 }
    });
    // Left accent
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cy, w: 0.06, h: cardH,
      fill: { color: w.color }
    });
    // Year
    slide.addText(w.year, {
      x: cx + 0.15, y: cy, w: 0.7, h: cardH,
      fontSize: 16, fontFace: "Georgia",
      color: theme.primary, bold: true,
      align: "left", valign: "middle", margin: 0
    });
    // Language
    slide.addText(w.lang, {
      x: cx + 0.9, y: cy, w: 1.8, h: cardH,
      fontSize: 13, fontFace: "Calibri",
      color: theme.primary, bold: false,
      align: "left", valign: "middle", margin: 0
    });
  });

  // Go insight callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.4, y: 4.65, w: 6.0, h: 0.4,
    fill: { color: theme.primary, transparency: 92 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.4, y: 4.65, w: 0.06, h: 0.4,
    fill: { color: theme.bg }
  });
  slide.addText("Go\u2019s 2016 win preceded its sharpest decline \u2014 now ranked 16th in March 2026", {
    x: 3.6, y: 4.65, w: 5.6, h: 0.4,
    fontSize: 10, fontFace: "Calibri",
    color: theme.primary, bold: false,
    align: "left", valign: "middle", margin: 0
  });

  // Source
  slide.addText("Source: TIOBE Programming Community Index, March 2026 | 2017 winner not available in source data", {
    x: 0.4, y: 5.25, w: 7, h: 0.3,
    fontSize: 8, fontFace: "Calibri",
    color: "999999", align: "left", valign: "middle", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "e76f51"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-05-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

